-- Pokemon Store Scanner > node "Garantir Schema das Lojas"
-- Backup de 13/08/2026.

CREATE TABLE IF NOT EXISTS lojas_confiaveis (id SERIAL PRIMARY KEY, slug TEXT NOT NULL UNIQUE, nome TEXT NOT NULL, official_store_id INTEGER, owner_id BIGINT, storefront_id TEXT, ativa BOOLEAN NOT NULL DEFAULT TRUE, prioridade SMALLINT NOT NULL DEFAULT 100, desconto_minimo NUMERIC(5,2) NOT NULL DEFAULT 15, preco_minimo NUMERIC(10,2) NOT NULL DEFAULT 0, preco_maximo NUMERIC(10,2), filtro_titulo TEXT, ultima_varredura TIMESTAMPTZ, ultimo_erro TEXT, produtos_ultima INTEGER, ofertas_ultima INTEGER, observacoes TEXT, criada_em TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX IF NOT EXISTS idx_lojas_confiaveis_ativa ON lojas_confiaveis (ativa, prioridade); ALTER TABLE promos ADD COLUMN IF NOT EXISTS idioma TEXT; ALTER TABLE promos ADD COLUMN IF NOT EXISTS idioma_confianca NUMERIC(3,2); INSERT INTO lojas_confiaveis (slug, nome, ativa, prioridade, desconto_minimo, filtro_titulo, observacoes) VALUES ('pokemon', 'Pokemon (loja oficial)', TRUE, 10, 10, NULL, 'Loja oficial da marca no Mercado Livre. Tudo que esta la ja e Pokemon, por isso nao ha filtro de titulo. Unica loja ativa no escopo atual.') ON CONFLICT (slug) DO NOTHING; INSERT INTO lojas_confiaveis (slug, nome, ativa, prioridade, desconto_minimo, filtro_titulo, observacoes) VALUES ('copag', 'COPAG', FALSE, 20, 15, 'pok[eé]mon|tcg|booster', 'Licenciada oficial do Pokemon TCG no Brasil. Cadastrada INATIVA por decisao de escopo. Ligue com: UPDATE lojas_confiaveis SET ativa = TRUE WHERE slug = ''copag''; [escopo 2026-08-13]') ON CONFLICT (slug) DO NOTHING; UPDATE lojas_confiaveis SET ativa = FALSE, observacoes = COALESCE(observacoes, '') || ' Cadastrada INATIVA por decisao de escopo: por enquanto so a loja oficial da Pokemon varre. Ligue com: UPDATE lojas_confiaveis SET ativa = TRUE WHERE slug = ''copag''; [escopo 2026-08-13]' WHERE slug = 'copag' AND COALESCE(observacoes, '') NOT LIKE '%[escopo 2026-08-13]%'; SELECT 1 AS schema_ok;
